import{_ as l,a0 as o,w as r,s as d,ao as t,I as i,x as s,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"編程基礎：Java 中的輸入和輸出 | LCTT x X-CMD","titleTemplate":false,"description":"編程基礎：Java 中的輸入和輸出 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"編程基礎：Java 中的輸入和輸出 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"編程基礎：Java 中的輸入和輸出 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210317 Programming 101- Input and output with Java","title":"編程基礎：Java 中的輸入和輸出","tag":"202107","desc":""},"relativePath":"202107/20210317 Programming 101- Input and output with Java.md","filePath":"[post].md"}'),c={name:"202107/20210317 Programming 101- Input and output with Java.md"};function u(h,a,g,m,v,k){const n=o("Link");return r(),d("div",null,[a[24]||(a[24]=t('<h1 id="編程基礎-java-中的輸入和輸出" tabindex="-1">編程基礎：Java 中的輸入和輸出 <a class="header-anchor" href="#編程基礎-java-中的輸入和輸出" aria-label="Permalink to “編程基礎：Java 中的輸入和輸出”">​</a></h1><blockquote><p>學習 Java 如何外理數據的讀與寫。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202107/27/101854by7yizpokqyo77kk.jpg" alt=""></p><p>當你寫一個程序時，你的應用程序可能需要讀取和寫入存儲在用户計算機上的文件。這在你想加載或存儲配置選項，你需要創建日誌文件，或你的用户想要保存工作以待後用的情況下是很常見的。每種語言處理這項任務的方式都有所不同。本文演示瞭如何用 Java 處理數據文件。</p><h3 id="安裝-java" tabindex="-1">安裝 Java <a class="header-anchor" href="#安裝-java" aria-label="Permalink to “安裝 Java”">​</a></h3>',5)),i("p",null,[a[1]||(a[1]=s("不管你的計算機是什麼平台，你都可以從 ",-1)),e(n,{href:"https://adoptopenjdk.net"},{default:p(()=>[...a[0]||(a[0]=[s("AdoptOpenJDK",-1)])]),_:1}),a[2]||(a[2]=s(" 安裝 Java。這個網站提供安全和開源的 Java 構建。在 Linux 上，你的軟件庫中也可能找到 AdoptOpenJDK 的構建。",-1))]),a[25]||(a[25]=i("p",null,"我建議你使用最新的長期支持（LTS）版本。最新的非 LTS 版本對希望嘗試最新 Java 功能的開發者來説是最好的，但它很可能超過大多數用户所安裝的版本 —— 要麼是系統上默認安裝的，要麼是以前為其他 Java 應用安裝的。使用 LTS 版本可以確保你與大多數用户所安裝的版本保持一致。",-1)),i("p",null,[a[4]||(a[4]=s("一旦你安裝好了 Java，就可以打開你最喜歡的文本編輯器並準備開始寫代碼了。你可能還想要研究一下 ",-1)),e(n,{href:"https://opensource.com/article/20/7/ide-java"},{default:p(()=>[...a[3]||(a[3]=[s("Java 集成開發環境",-1)])]),_:1}),a[5]||(a[5]=s("。BlueJ 是新程序員的理想選擇，而 Eclipse 和 Netbeans 對中級和有經驗的編碼者更友好。",-1))]),a[26]||(a[26]=t(`<h3 id="利用-java-讀取文件" tabindex="-1">利用 Java 讀取文件 <a class="header-anchor" href="#利用-java-讀取文件" aria-label="Permalink to “利用 Java 讀取文件”">​</a></h3><p>Java 使用 <code>File</code> 類來加載文件。</p><p>這個例子創建了一個叫 <code>Ingest</code> 的類來讀取文件中數據。當你要在 Java 中打開一個文件時，你創建了一個 <code>Scanner</code> 對象，它可以逐行掃描你提供的文件。事實上，<code>Scanner</code> 與文本編輯器中的光標是相同的概念，這樣你可以用 <code>Scanner</code> 的一些方法（如 <code>nextLine</code>）來控制這個“光標”以進行讀寫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import java.io.File;</span></span>
<span class="line"><span>import java.util.Scanner;</span></span>
<span class="line"><span>import java.io.FileNotFoundException;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>public class Ingest {</span></span>
<span class="line"><span>  public static void main(String[] args) {</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span>      try {</span></span>
<span class="line"><span>          File myFile = new File(&quot;example.txt&quot;);</span></span>
<span class="line"><span>          Scanner myScanner = new Scanner(myFile);</span></span>
<span class="line"><span>          while (myScanner.hasNextLine()) {</span></span>
<span class="line"><span>              String line = myScanner.nextLine();</span></span>
<span class="line"><span>              System.out.println(line);</span></span>
<span class="line"><span>          }</span></span>
<span class="line"><span>          myScanner.close();</span></span>
<span class="line"><span>      } catch (FileNotFoundException ex) {</span></span>
<span class="line"><span>          ex.printStackTrace();  </span></span>
<span class="line"><span>      } //try</span></span>
<span class="line"><span>    } //main</span></span>
<span class="line"><span>} //class</span></span></code></pre></div><p>這段代碼首先在假設存在一個名為 <code>example.txt</code> 的文件的情況下創建了變量 <code>myfile</code>。如果該文件不存在，Java 就會“拋出一個異常”（如它所説的，這意味着它在你試圖做的事情中發現了一個錯誤），這個異常是被非常特定的 <code>FileNotFoundException</code> 類所“捕獲”。事實上，有一個專門的類來處理這個明確的錯誤，這説明這個錯誤是多麼常見。</p><p>接下來，它創建了一個 <code>Scanner</code> 並將文件加載到其中。我把它叫做 <code>myScanner</code>，以區別於它的通用類模板。接着，一個 <code>while</code> 循環將 <code>myScanner</code> 逐行送入文件中，只要 <em>存在</em> 下一行。這就是 <code>hasNextLine</code> 方法的作用：它檢測“光標”之後是否還有數據。你可以通過在文本編輯器中打開一個文件來模擬這個過程：你的光標從文件的第一行開始，你可以用鍵盤控制光標來向下掃描文件，直到你走完了所有的行。</p><p><code>while</code> 循環創建了一個變量 <code>line</code>，並將文件當前行的數據分配給它。然後將 <code>line</code> 的內容打印出來以提供反饋。一個更有用的程序可能會解析每一行的內容，從而提取它所包含的任何重要數據。</p><p>在這個過程結束時，關閉 <code>myScanner</code> 對象。</p><h3 id="運行代碼" tabindex="-1">運行代碼 <a class="header-anchor" href="#運行代碼" aria-label="Permalink to “運行代碼”">​</a></h3><p>將你的代碼保存到 <code>Ingest.java</code> 文件（這是一個 Java 慣例，將類名的首字母大寫，並以類名來命名相應的文件）。如果你試圖運行這個簡單的應用程序，你可能會接收到一個錯誤信息，這是因為還沒有 <code>example.txt</code> 文件供應用程序加載:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java ./Ingest.java</span></span>
<span class="line"><span>java.io.FileNotFoundException:</span></span>
<span class="line"><span>example.txt (No such file or directory)</span></span></code></pre></div><p>正好可以編寫一個將數據寫入文件的 Java 應用程序，多麼完美的時機！</p><h3 id="利用-java-將數據寫入文件" tabindex="-1">利用 Java 將數據寫入文件 <a class="header-anchor" href="#利用-java-將數據寫入文件" aria-label="Permalink to “利用 Java 將數據寫入文件”">​</a></h3><p>無論你是存儲用户使用你的應用程序創建的數據，還是僅僅存儲關於用户在應用程序中做了什麼的元數據（例如，遊戲保存或最近播放的歌曲），有很多很好的理由來存儲數據供以後使用。在 Java 中，這是通過 <code>FileWriter</code> 類實現的，這次先打開一個文件，向其中寫入數據，然後關閉該文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import java.io.FileWriter;</span></span>
<span class="line"><span>import java.io.IOException;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>public class Exgest {</span></span>
<span class="line"><span>  public static void main(String[] args) {</span></span>
<span class="line"><span>    try {</span></span>
<span class="line"><span>        FileWriter myFileWriter = new FileWriter(&quot;example.txt&quot;, true);</span></span>
<span class="line"><span>        myFileWriter.write(&quot;Hello world\\n&quot;);</span></span>
<span class="line"><span>        myFileWriter.close();</span></span>
<span class="line"><span>    } catch (IOException ex) {</span></span>
<span class="line"><span>        System.out.println(ex);</span></span>
<span class="line"><span>    } // try</span></span>
<span class="line"><span>  } // main</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這個類的邏輯和流程與讀取文件類似。但它不是一個 <code>Scanner</code>，而是以一個文件的名字為參數創建的一個 <code>FileWriter</code> 對象。<code>FileWriter</code> 語句末尾的 <code>true</code> 標誌告訴 <code>FileWriter</code> 將文本 <em>追加</em> 到文件的末尾。要覆蓋一個文件的內容，請移除 <code>true</code> 標誌。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\`FileWriter myFileWriter = new FileWriter(&quot;example.txt&quot;, true);\`</span></span></code></pre></div><p>因為我在向文件中寫入純文本，所以我在寫入文件的數據（<code>Hello world</code>）的結尾處手動添加了換行符（<code>\\n</code>）。</p><h3 id="試試代碼" tabindex="-1">試試代碼 <a class="header-anchor" href="#試試代碼" aria-label="Permalink to “試試代碼”">​</a></h3><p>將這段代碼保存到 <code>Exgest.java</code> 文件，遵循 Java 的慣例，使文件名為與類名相匹配。</p><p>既然你已經掌握了用 Java 創建和讀取數據的方法，你可以按相反的順序嘗試運行你的新應用程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java ./Exgest.java</span></span>
<span class="line"><span>$ java ./Ingest.java</span></span>
<span class="line"><span>Hello world</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>因為程序是把數據追加到文件末尾，所以你可以重複執行你的應用程序以多次寫入數據，只要你想把更多的數據添加到你的文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java ./Exgest.java</span></span>
<span class="line"><span>$ java ./Exgest.java</span></span>
<span class="line"><span>$ java ./Exgest.java</span></span>
<span class="line"><span>$ java ./Ingest.java</span></span>
<span class="line"><span>Hello world</span></span>
<span class="line"><span>Hello world</span></span>
<span class="line"><span>Hello world</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="java-和數據" tabindex="-1">Java 和數據 <a class="header-anchor" href="#java-和數據" aria-label="Permalink to “Java 和數據”">​</a></h3><p>你不會經常向文件中寫入原始文本；事實上，你可能會使用一個其它的類庫以寫入特定的格式。例如，你可能使用 XML 類庫來寫複雜的數據，使用 INI 或 YAML 類庫來寫配置文件，或者使用各種專門類庫來寫二進制格式，如圖像或音頻。</p>`,26)),i("p",null,[a[7]||(a[7]=s("更完整的信息，請參閲 ",-1)),e(n,{href:"https://access.redhat.com/documentation/en-us/openjdk/11/"},{default:p(()=>[...a[6]||(a[6]=[s("OpenJDK 文檔",-1)])]),_:1}),a[8]||(a[8]=s("。",-1))]),a[27]||(a[27]=i("hr",null,null,-1)),i("p",null,[a[10]||(a[10]=s("via: ",-1)),e(n,{href:"https://opensource.com/article/21/3/io-java"},{default:p(()=>[...a[9]||(a[9]=[s("https://opensource.com/article/21/3/io-java",-1)])]),_:1})]),i("p",null,[a[15]||(a[15]=s("作者：",-1)),e(n,{href:"https://opensource.com/users/seth"},{default:p(()=>[...a[11]||(a[11]=[s("Seth Kenlon",-1)])]),_:1}),a[16]||(a[16]=s(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...a[12]||(a[12]=[s("lujun9972",-1)])]),_:1}),a[17]||(a[17]=s(" 譯者：",-1)),e(n,{href:"https://github.com/piaoshi"},{default:p(()=>[...a[13]||(a[13]=[s("piaoshi",-1)])]),_:1}),a[18]||(a[18]=s(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...a[14]||(a[14]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[21]||(a[21]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...a[19]||(a[19]=[s("LCTT",-1)])]),_:1}),a[22]||(a[22]=s(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...a[20]||(a[20]=[s("Linux中國",-1)])]),_:1}),a[23]||(a[23]=s(" 榮譽推出",-1))])])}const y=l(c,[["render",u]]);export{f as __pageData,y as default};
